// Runs a design: "design X on layout Y at animation time t" -> the 8-bit
// values the chain receives, the supply current, and what the eye sees.
//
// A design is
//   export default {
//     name, blurb,
//     layouts: ['hex'],        // layouts it is drawn for; '*' = any (first is the default)
//     look: 'bare',            // how it is meant to be seen: bare | smoke | opal (+ gap)
//     fps: 60,
//     brightness: 0.5,         // global scale on everything it draws (default 1)
//     dither: false,           // temporal dithering of the 8-bit values
//     warmup: 0,               // seconds of history a stateful design needs
//     init(ctx) {},            // optional, once per run: set up ctx.state
//     frame(ctx) {},           // draw: write linear colour into ctx.out
//   }
//
// frame(ctx) gets
//   ctx.t        animation seconds;  ctx.dt  seconds since the last frame
//   ctx.date     the wall clock (a Date);  ctx.night  0 day .. 1 night
//   ctx.leds     every LED: { i, x, y (mm), panel, type, col, hr|row, ring, ringPos, ringLen, gx, gy }
//   ctx.n, ctx.layout (bbox, panels, lattice, index.near/at)
//   ctx.out      Float32Array(3n), zeroed each frame: linear light 0..1
//   ctx.state    the design's own, kept between frames
//
// Stateful designs are made deterministic by replay: to show time t the
// player runs from t - warmup at the design's fps, so any instant can be
// rendered on its own and gives the same picture as a live run.

import { layout as getLayout, LAYOUTS } from '../../skills/ws2812-clock/sim/js/layout.js';
import { quantize, currentA } from '../../skills/ws2812-clock/sim/js/ws2812.js';
import * as kit from '../../skills/ws2812-clock/sim/js/kit.js';
const DESIGNS = {};   // filled one design at a time by faces/load.js

export { DESIGNS, LAYOUTS };

/** The date renders are anchored to, so they are reproducible. */
const BASE_DATE = new Date(2026, 9, 5);

/** Wall clock at animation time t, given the clock shown at t = 0 ("HH:MM:SS"). */
export function dateFor(clock = '10:09:30', t = 0) {
  const [h = 10, m = 9, s = 30] = String(clock).split(':').map(Number);
  const d = new Date(BASE_DATE);
  d.setHours(h, m, Math.floor(s), Math.round((s % 1) * 1000));
  return new Date(d.getTime() + t * 1000);
}

export function layoutFor(design, override) {
  const ok = design.layouts ?? ['*'];
  const key = override ?? (ok[0] === '*' ? 'hex' : ok[0]);
  return getLayout(key);
}

/**
 * A runner for one design on one layout.
 *   opts: { layout, clock (at t = 0, or a Date via `date0`), night: 'auto'|'off'|'on', fps }
 * run.at(t) -> { values (Uint8Array 3n), duty (Float32Array 3n, what the eye sees),
 *                amps, ms (time spent in frame()) }
 */
export function runner(design, opts = {}) {
  const L = layoutFor(design, opts.layout);
  const fps = Number(opts.fps ?? design.fps ?? 60);
  const date0 = opts.date0 ?? dateFor(opts.clock, 0);
  const n = L.n;
  const out = new Float32Array(3 * n), values = new Uint8Array(3 * n), duty = new Float32Array(3 * n);
  const carry = design.dither ? new Float32Array(3 * n) : null;
  const bright = design.brightness ?? 1;
  // HUB75 panels dim with their output-enable pulse, not by scaling the
  // values: they get the full 8 bits at any brightness. So their values are
  // quantised at full scale (vScale 1) and the brightness lands on the duty.
  const hub = L.leds.some((l) => L.panels[l.panel].def.bus === 'hub75');
  const vScale = hub ? new Float32Array(3 * n) : bright, post = hub ? new Float32Array(3 * n) : null;
  if (hub) for (const l of L.leds) {
    const isHub = L.panels[l.panel].def.bus === 'hub75';
    for (let c = 0; c < 3; c++) { vScale[3 * l.i + c] = isHub ? 1 : bright; post[3 * l.i + c] = isHub ? bright / 255 : 1 / 255; }
  }
  let ctx = null, last = null;

  function reset() {
    ctx = { t: 0, dt: 1 / fps, n, leds: L.leds, layout: L, out, state: {}, kit, fps };
    carry?.fill(0);
    design.init?.(ctx);
    last = null;
  }

  function step(t) {
    const date = new Date(date0.getTime() + t * 1000);
    ctx.dt = last === null ? 1 / fps : t - last;
    ctx.t = t; ctx.date = date;
    ctx.night = opts.night === 'off' ? 0 : opts.night === 'on' ? 1 : kit.nightLevel(date);
    out.fill(0);
    const t0 = performance.now();
    design.frame(ctx);
    const ms = performance.now() - t0;
    quantize(out, values, vScale, carry);
    last = t;
    return ms;
  }

  reset();
  return {
    layout: L, fps, design,
    at(t) {
      const warm = design.warmup ?? 0;
      const ahead = last === null ? -1 : t - last;
      if (warm <= 0) {
        // stateless: any instant stands on its own; only going back resets
        // (so dithering stays continuous while time runs forward)
        if (ahead <= 0) reset();
      } else if (ahead > 0 && ahead <= Math.min(warm, 2)) {
        // stateful, a short step forward: run the frames in between, as
        // the hardware would
        for (let s = last + 1 / fps; s < t - 1e-9; s += 1 / fps) step(s);
      } else {
        reset();
        for (let s = Math.max(0, t - warm); s < t - 1e-9; s += 1 / fps) step(s);
      }
      const ms = step(t);
      // Dithered values flicker between levels; the eye sees their average,
      // which is the unrounded target.
      if (carry) for (let k = 0; k < 3 * n; k++) duty[k] = kit.clamp(out[k]) * bright;
      else if (post) for (let k = 0; k < 3 * n; k++) duty[k] = values[k] * post[k];
      else for (let k = 0; k < 3 * n; k++) duty[k] = values[k] / 255;
      return { values, duty, amps: currentA(L, duty), ms, date: ctx.date };
    },
  };
}
